DELETE FROM sent_log;
DELETE FROM attachments;
DELETE FROM drafts;
DELETE FROM messages;
DELETE FROM folders;
DELETE FROM account_config;
DELETE FROM _counters;

-- OFFICIAL_SOURCE_CACHE_V2 inserted from public official-source crawl, frozen for offline task replay.
UPDATE messages
SET subject = CASE from_addr
      WHEN 'bank@example.com' THEN 'Checking and reserve activity summary · ' || substr(date,1,10)
      WHEN 'card@example.com' THEN 'Card statement, due date, and payment status · ' || substr(date,1,10)
      WHEN 'irs@example.gov' THEN 'IRS beneficiary or estimated-tax correspondence · ' || substr(date,1,10)
      WHEN 'servicer@example.com' THEN 'Northstar custodian processing note · ' || substr(date,1,10)
      WHEN 'brokerage@example.com' THEN 'Household brokerage cash and position note · ' || substr(date,1,10)
      WHEN 'calendar@example.com' THEN 'Finance review schedule update · ' || substr(date,1,10)
      WHEN 'clinic@example.com' THEN 'Medical invoice and reimbursement support · ' || substr(date,1,10)
      WHEN 'employer@example.com' THEN 'Income and withholding record · ' || substr(date,1,10)
      WHEN 'insurance@example.com' THEN 'Coverage, premium, or claim record · ' || substr(date,1,10)
      WHEN 'dealer@example.com' THEN 'Auto-loan statement or service invoice · ' || substr(date,1,10)
      ELSE subject
    END,
    body_text = CASE from_addr
      WHEN 'bank@example.com' THEN 'Bank record for ' || substr(date,1,10) || ': reconcile ordinary checking, bill-pay cash, scheduled payments, and the separately restricted estate reserve. Message UID ' || uid || '.'
      WHEN 'card@example.com' THEN 'Card record for ' || substr(date,1,10) || ': verify statement balance, minimum due, APR, purchases, payment authorization, and actual payment status. Message UID ' || uid || '.'
      WHEN 'irs@example.gov' THEN 'Official-tax correspondence for ' || substr(date,1,10) || ': distinguish general beneficiary guidance and estimated-tax dates from Leah-specific custodian and CPA facts. Message UID ' || uid || '.'
      WHEN 'servicer@example.com' THEN 'Custodian record for ' || substr(date,1,10) || ': track beneficiary registration, missing documents, election prerequisites, withholding instruction, and processing status. Message UID ' || uid || '.'
      WHEN 'brokerage@example.com' THEN 'Brokerage record for ' || substr(date,1,10) || ': household positions and cash are separate from the inherited account; no order is implied by this notice. Message UID ' || uid || '.'
      WHEN 'calendar@example.com' THEN 'Calendar record for ' || substr(date,1,10) || ': next CPA, custodian, card, source, and household-liquidity reviews are tracked as separate appointments. Message UID ' || uid || '.'
      WHEN 'clinic@example.com' THEN 'Medical record for ' || substr(date,1,10) || ': retain invoice, patient responsibility, reimbursement status, and payment evidence before classifying cash need. Message UID ' || uid || '.'
      WHEN 'employer@example.com' THEN 'Income record for ' || substr(date,1,10) || ': classify payroll or consulting income separately from inherited-IRA distributions and withholding. Message UID ' || uid || '.'
      WHEN 'insurance@example.com' THEN 'Insurance record for ' || substr(date,1,10) || ': verify premium, coverage, claim, or refund status and do not assume pending amounts are cash. Message UID ' || uid || '.'
      WHEN 'dealer@example.com' THEN 'Auto record for ' || substr(date,1,10) || ': reconcile loan statement, service invoice, due date, and ordinary-cash impact. Message UID ' || uid || '.'
      ELSE body_text
    END
WHERE from_addr IN ('bank@example.com','card@example.com','irs@example.gov','servicer@example.com','brokerage@example.com','calendar@example.com','clinic@example.com','employer@example.com','insurance@example.com','dealer@example.com');

UPDATE drafts
SET subject = 'Unsent finance follow-up · draft ' || id,
    body_text = CASE id % 6
      WHEN 0 THEN 'Draft only: ask the custodian to confirm beneficiary registration and any year-of-death distribution before an election.'
      WHEN 1 THEN 'Draft only: ask the CPA to review income, withholding assumptions, and estimated-tax timing.'
      WHEN 2 THEN 'Draft only: request receipts and executor approval for the family reimbursement request.'
      WHEN 3 THEN 'Draft only: reconcile the card statement and payment result before reporting it as completed.'
      WHEN 4 THEN 'Draft only: confirm the estate reserve remains restricted and document any proposed exception.'
      ELSE 'Draft only: schedule the next custodian, CPA, source, and household-liquidity reviews.'
    END;

-- The second draft set records distinct unresolved follow-ups rather than cloning the first set.
UPDATE drafts SET body_text='Draft only: ask the CPA whether the decedent had begun required distributions and which documents would resolve the year-of-death question.' WHERE id=7;
UPDATE drafts SET body_text='Draft only: ask the executor for the funeral travel receipt, claimant name, estate purpose, and written reimbursement authority.' WHERE id=8;
UPDATE drafts SET body_text='Draft only: request the card issuer settlement reference, posting date, and remaining unbilled balance after the authorized payment.' WHERE id=9;
UPDATE drafts SET body_text='Draft only: document the reserve-account source restriction and ask counsel whether any estate expense exception applies.' WHERE id=10;
UPDATE drafts SET body_text='Draft only: propose separate dates for the custodian callback, CPA fact review, card due-date check, and household liquidity refresh.' WHERE id=11;
UPDATE drafts SET body_text='Draft only: ask Northstar Custody to identify the beneficiary registration, election prerequisites, withholding choices, and acceptance status.' WHERE id=12;
